// CARD-0195/CARD-0196/CARD-0216: hiking-monitor's field-mode skip-reason/reset-reason/
// display-refresh records ride the same flash-buffer-then-replay path real
// sensor readings use, so they arrive on this same jctsh/components/+/data
// wildcard topic. They aren't real readings -- don't send them through
// GPS lookup or into the Environmental Data sheet; convert them to a
// standard log message on the component's own /log topic instead.
var d = msg.payload;
if (typeof d === 'string') {
    try { d = JSON.parse(d); } catch(e) { node.warn('Bad JSON: ' + msg.payload); return [null, null]; }
}
var parts = msg.topic.split('/'); // jctsh/components/<name>/data
var component = parts[2] || 'unknown';
if (d.event === 'skip' || d.event === 'reset' || d.event === 'display_refresh') {
    var category, message;
    if (d.event === 'reset') {
        // CARD-0216: firmware now logs every field-mode boot's reset
        // reason unconditionally (not just abnormal ones) to catch a
        // silently-rebooting device -- categorize here instead, same
        // abnormal-keyword check the firmware used to do, so a normal
        // hike-start wake doesn't post as a false Alert every hike.
        var reason = d.reason || '';
        var abnormal = /rownout|anic|atchdog/.test(reason);
        category = abnormal ? 'Alert' : 'System';
        message = (abnormal ? 'Unexpected reset in field mode - ' : 'Field-mode boot, reset reason: ') + reason;
    } else if (d.event === 'display_refresh') {
        // CARD-0196: real event time from the record's own ts field, not
        // receipt time -- every buffered record lands in the same ~1s
        // bulk-replay burst at hike-end regardless of when it actually
        // happened, so receipt time alone can't show the ~20min cadence.
        category = 'System';
        message = 'Display refreshed (field mode) at ' + d.ts;
    } else {
        category = 'System';
        message = 'Skipped reading - ' + d.reason;
        if (d.temp !== undefined) {
            message += ' (temp=' + d.temp + ', hum=' + d.hum + ', pres=' + d.pres + ')';
        }
    }
    var logMsg = {
        topic: 'jctsh/components/' + component + '/log',
        payload: JSON.stringify({component: component, category: category, message: message})
    };
    return [logMsg, null];
}
msg.payload = d;
return [null, msg];

var d = msg.payload;
if (typeof d === 'string') {
    try { d = JSON.parse(d); } catch(e) { node.warn('Bad JSON: ' + msg.payload); return null; }
}
msg._sensorData = d;

// CARD-0306: a device that already knows its own fixed location (e.g.
// front-porch-temp-sensor, hardcoded per house-lot-coordinates.md) sends
// non-null lat/lon itself -- skip the GPS-Track correlation lookup
// entirely for it. Two reasons, not just one: (1) the lookup call is
// pointless for a device that already knows its own coordinates, and
// (2) left unskipped, a match against the GPS Track sheet (populated
// only by an active hike) would silently overwrite this device's own
// correct coordinate with wherever the hiker happens to be at that
// moment -- a real geotagging-correctness bug, not just wasted calls.
if (d.lat !== null && d.lat !== undefined) {
    msg.payload = d;
    return [null, msg];
}

// CARD-0279: retry counter for the lookup-failure loop below -- reset
// here (not just on first pass through the throttle node) so a message
// that somehow re-enters this node fresh doesn't inherit a stale count.
msg._lookupAttempt = 1;
var ts = d.ts || '';
msg.url = env.get('APPS_SCRIPT_URL') + '?key=' + encodeURIComponent(env.get('APPS_SCRIPT_KEY')) + '&action=lookup&ts=' + encodeURIComponent(ts);
msg.payload = '';
return [msg, null];

// CARD-0279: field-mode's replay-at-reconnect burst can fire dozens of
// these lookup calls at Apps Script within a few seconds (throttled to
// 2/sec by the delay node upstream, but Apps Script can still be slow
// enough under that load to time out or error on an individual call --
// this used to fail silently with no retry and no trace anywhere).
// Outputs: [0] continue downstream (success, confirmed miss, or retries
// exhausted) -- [1] retry (loops back through the throttle node) --
// [2] log a failure, only populated on the final exhausted attempt.
var d = msg._sensorData;
var attempt = msg._lookupAttempt || 1;
var MAX_ATTEMPTS = 3;

if (msg.statusCode === 200) {
    // A 200 covers both a real match and a confirmed "no GPS Track point
    // within 5 min" miss -- environmental-data.gs's own _gpsLookup()
    // already logs a genuine miss server-side (Correlation Debug sheet,
    // CARD-0197). Either way this call is resolved; not a retry case.
    try {
        var gps = JSON.parse(msg.payload);
        if (gps.lat !== null && gps.lat !== undefined) {
            d.lat = gps.lat;
            d.lon = gps.lon;
        }
    } catch (e) { /* malformed body -- resolved-but-no-coords, not worth retrying a parse error */ }
    // Hiking monitor at home has no GPS track -- use garage front wall (H6-H7 midpoint).
    // rssi_dbm is 0 for field readings (no WiFi); non-zero confirms home WiFi.
    if (d.component === 'hiking-monitor' && (d.lat === null || d.lat === undefined) && d.rssi_dbm !== 0) {
        d.lat = 32.4612842;
        d.lon = -111.1183818;
    }
    msg.payload = d;
    return [msg, null, null];
}

// Non-200 (timeout, network error, Apps Script overload under this
// burst's own concurrency) -- retry a bounded number of times before
// giving up.
if (attempt < MAX_ATTEMPTS) {
    msg._lookupAttempt = attempt + 1;
    return [null, msg, null];
}

// Retries exhausted -- log so this isn't silent, then continue with no
// coordinates rather than dropping the reading entirely.
var failMsg = {
    topic: 'jctsh/core/log-server/log',
    payload: JSON.stringify({
        component: 'node-red', category: 'Alert',
        message: 'GPS lookup failed after ' + MAX_ATTEMPTS + ' attempts for ' + d.component +
            ' reading @ ' + d.ts + ' (status ' + (msg.statusCode || 'no response') + ') -- publishing without coordinates.'
    })
};
msg.payload = d;
return [msg, null, failMsg];

// Parse payload
var d = msg.payload;
if (typeof d === 'string') {
    try { d = JSON.parse(d); } catch(e) { node.warn('Bad JSON: ' + msg.payload); return null; }
}

// Add source field
d.source = d.component;

// Compute dew point and heat index if temp + humidity available
if (d.temp_f != null && d.humidity_pct != null) {
    var temp_c = (d.temp_f - 32) * 5 / 9;
    var a = 17.27, b = 237.7;
    var gamma = (a * temp_c / (b + temp_c)) + Math.log(d.humidity_pct / 100);
    var dew_c = (b * gamma) / (a - gamma);
    d.dew_point_f = Math.round((dew_c * 9/5 + 32) * 10) / 10;

    var T = d.temp_f, H = d.humidity_pct;
    if (T >= 80 && H >= 40) {
        d.heat_index_f = Math.round((
            -42.379 + 2.04901523*T + 10.14333127*H
            - 0.22475541*T*H - 0.00683783*T*T - 0.05481717*H*H
            + 0.00122874*T*T*H + 0.00085282*T*H*H
            - 0.00000199*T*T*H*H
        ) * 10) / 10;
    } else {
        d.heat_index_f = Math.round((T + H/5 - 10.3) * 10) / 10;
    }
}

// Build HTTP POST
msg.url = env.get('APPS_SCRIPT_URL') + '?key=' + encodeURIComponent(env.get('APPS_SCRIPT_KEY'));
msg.method = 'POST';
msg.headers = {'Content-Type': 'application/json'};
msg.payload = JSON.stringify(d);
msg._component = d.component;
return msg;

// CARD-0226 (2026-09-24): serial POST queue. Readings used to be POSTed to
// Apps Script concurrently (2/s after the GPS throttle) and any failure was
// invisible -- a real 121-reading replay landed only ~20% of its rows with
// zero alerts. Now: one POST in flight at a time; every reply is checked
// (see "Check response"); anything that isn't ok/duplicate is retried with
// backoff (safe -- Apps Script rejects an exact (ts, source) duplicate), and
// a reading that still fails is reported as an Alert instead of vanishing.
// Two inputs on this one node: a new reading (from "Compute derived fields +
// build POST") or a result (msg._queueDone, from "Check response").
// Output 1 -> POST to Apps Script, output 2 -> log Alert.
var st = context.get('st');
if (!st) { st = { q: [], busy: false, cur: null, seq: 0, timer: null }; context.set('st', st); }
var MAX_ATTEMPTS = 5;
var BACKOFF_MS = [0, 3000, 8000, 15000, 30000];
var WATCHDOG_MS = 150000;

function alertMsg(text) {
    return { payload: JSON.stringify({ component: 'node-red', category: 'Alert', message: text }) };
}
function describe(item) {
    var ts = '?';
    try { ts = JSON.parse(item.msg.payload).ts; } catch (e) {}
    return item.msg._component + ' reading @ ' + ts;
}
function dispatch(item) {
    st.busy = true;
    st.cur = item;
    item.waiting = false;
    st.seq += 1;
    item.seq = st.seq;
    var out = RED.util.cloneMessage(item.msg);
    out._seq = item.seq;
    out._attempt = item.attempt;
    out.followRedirects = false;
    clearTimeout(st.timer);
    var seq = item.seq;
    st.timer = setTimeout(function () {
        if (st.cur && st.cur.seq === seq && !st.cur.waiting) {
            settle(item, 'retry', 'no response within ' + (WATCHDOG_MS / 1000) + 's');
        }
    }, WATCHDOG_MS);
    node.send([out, null]);
}
function next() {
    st.busy = false;
    st.cur = null;
    if (st.q.length > 0) dispatch(st.q.shift());
}
function settle(item, result, detail) {
    clearTimeout(st.timer);
    if (result === 'ok' || result === 'duplicate') { next(); return; }
    if (result === 'rejected') {
        node.send([null, alertMsg('Environmental Data POST rejected for ' + describe(item) + ' -- ' + detail)]);
        next();
        return;
    }
    if (item.attempt < MAX_ATTEMPTS) {
        var wait = BACKOFF_MS[item.attempt] || 30000;
        item.attempt += 1;
        item.waiting = true;
        st.timer = setTimeout(function () { dispatch(item); }, wait);
        return;
    }
    node.send([null, alertMsg('Environmental Data POST failed for ' + describe(item) + ' after ' +
        MAX_ATTEMPTS + ' attempts (' + detail + ') -- reading NOT written to the sheet.')]);
    next();
}

if (msg._queueDone) {
    if (!st.cur || st.cur.waiting || st.cur.seq !== msg._seq) return null;
    settle(st.cur, msg._result, msg._detail || '');
    return null;
}
st.q.push({ msg: msg, attempt: 1 });
if (!st.busy) dispatch(st.q.shift());
return null;

// CARD-0226: Apps Script answers every POST with a redirect to the real
// response. Node-RED used to follow it with POST (-> a useless 405 that was
// treated as success). "POST queue" now disables redirect-following, so the
// first reply is the 302 -- fetch its Location with a plain GET to read the
// script's actual JSON. Anything that is not a redirect (network error,
// direct 200) skips the GET and goes straight to "Check response".
var s = msg.statusCode;
var loc = msg.headers && (msg.headers.location || msg.headers.Location);
if ((s === 301 || s === 302 || s === 303 || s === 307 || s === 308) && loc) {
    return [{
        _seq: msg._seq, _attempt: msg._attempt, _component: msg._component,
        url: loc, method: 'GET', headers: {}, followRedirects: true
    }, null];
}
return [null, msg];

// CARD-0226: classify the script's REAL reply (fetched by "Get Apps Script
// result") and hand it back to the POST queue, which retries or alerts.
// ok / duplicate = written (or already there); rejected = out-of-range sensor
// values, deliberate, not retried; anything else (lock timeout -> status
// 'error', an HTML error page, a network error, no JSON) = retry.
var status = msg.statusCode || 0;
var payload = (typeof msg.payload === 'string') ? msg.payload : JSON.stringify(msg.payload);
var out = { _queueDone: true, _seq: msg._seq, _component: msg._component || 'unknown' };
var resp = null;
try { resp = JSON.parse(payload); } catch (e) {}
if (resp && (resp.status === 'ok' || resp.status === 'duplicate')) {
    out._result = resp.status;
} else if (resp && resp.status === 'rejected') {
    out._result = 'rejected';
    out._detail = payload.slice(0, 150);
} else {
    out._result = 'retry';
    out._detail = 'HTTP ' + status + ': ' + String(payload).replace(/\s+/g, ' ').slice(0, 120);
}
return out;
